window.__posterData({"id": "tuva-naring", "name": "Tuva Naring", "folder": "Week1_AIPoster_TuvaNaring", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Tuva Naring + AI – SKOG / SKOGS RAVE\n\nconst NOISE_SCALE = 0.005;\nconst SCROLL_SPEED = 1.5;\n\n// Skogslager: noise-offset, amplitud och bas-höjd (px från botten)\nconst forestLayers = [\n  { noiseOffset: 10, amplitude: 140, baseHeight: 260 },\n  { noiseOffset: 20, amplitude: 150, baseHeight: 180 },\n  { noiseOffset: 30, amplitude: 130, baseHeight: 100 },\n  { noiseOffset: 40, amplitude: 100, baseHeight: 30 },\n];\nconst LASER_LAYER_INDEX = 2; // lasrarna ritas före detta lager\n\n// Claude skrev om typ allt i min kod till en \"mer effektiv\" version med mycket nya funktioner/benämningar på objekt. Lite obekvämt att den tar ens kod och på 2 sekunder gör om allt sjukt mycket bättre än man själv gjort. Uppmanade också att jag skulle ladda ner google fonts som den själv valt ut till texten, inte jättestort fan av att maskinen vill att jag ska ladda ner saker det känns underligt. Claude la också till fler laser när jag bad den koda att de rör sig uniformt istället för osynkat. \n\n\n// Laserkällor: jämnt fördelade över bredden\nconst LASER_COLORS = [\n  [0, 255, 255],\n  [255, 0, 255],\n  [100, 50, 255],\n  [0, 150, 255],\n  [255, 0, 200],\n  [0, 255, 180],\n  [150, 50, 255],\n  [0, 200, 255],\n];\nconst LASER_COUNT = 20;\nconst LASER_SPACING = 600 / LASER_COUNT;\nconst LASER_FAN_SPREAD = 0.6;\n\nconst laserSources = Array.from({ length: LASER_COUNT }, (_, i) => ({\n  x: LASER_SPACING * (i + 0.5),\n  angle: -LASER_FAN_SPREAD / 2 + (LASER_FAN_SPREAD * i) / (LASER_COUNT - 1),\n  color: LASER_COLORS[i % LASER_COLORS.length],\n}));\n\nconst LASER_LENGTH = 800;\nconst LASER_WEIGHT = 10;\nconst LASER_GLOW = 35;\nconst LASER_SWAY = 0.25;\nconst LASER_SWAY_SPEED = 0.025;\n\n// Partyläge (musknapp nedtryckt på natten)\nconst STROBE_SPEED = 0.6;      // hur snabbt lasrarna blinkar\nconst SWAY_BOOST = 3;          // hur mycket snabbare fläkten svänger\nconst PARTICLES_PER_FRAME = 4;\nconst GRAVITY = 0.15;\n\nlet partyMode = false;\nlet particles = [];\n\n// Titel\nconst TITLE_Y1 = 70;   // rad 1: SKOG(S)\nconst TITLE_Y2 = 135;  // rad 2: RAVE\nconst TITLE_SIZE = 56;\n\nlet fontGraffiti; // Rock Salt\nlet fontBody;     // Permanent Marker\n\nlet scrollOffset = 0;\nlet toggleState = false; // false = dag, true = natt\n\nlet originalColors = [];\nlet layerColors = [];\nlet originalBgColor;\nlet bgColor;\n\nlet galaxy;\nlet galaxyLoaded = false;\n\nasync function setup() {\n  createCanvas(600, 800);\n\n  fontGraffiti = await loadFont('RockSalt-Regular.ttf');\n  fontBody = await loadFont('PermanentMarker-Regular.ttf');\n\n  galaxy = await loadImage('galaxysky.jpg');\n  galaxyLoaded = true;\n\n  originalColors = [\n    color(39, 154, 47),\n    color(39, 140, 50),\n    color(45, 145, 40),\n    color(35, 130, 40),\n  ];\n  originalBgColor = color(184, 214, 255);\n\n  layerColors = [...originalColors];\n  bgColor = originalBgColor;\n}\n\nfunction draw() {\n  // vänta tills allt är laddat (draw kan köras medan setup väntar)\n  if (!fontBody || !galaxyLoaded) return;\n\n  if (toggleState) {\n    image(galaxy, 0, 0, width, height);\n  } else {\n    background(bgColor);\n  }\n\n  scrollOffset += SCROLL_SPEED;\n\n  forestLayers.forEach((layer, i) => {\n    if (toggleState && i === LASER_LAYER_INDEX) drawLasers();\n    drawForestLayer(layer, layerColors[i]);\n  });\n\n  updateParticles();\n  drawTitle();\n}\n\nfunction drawForestLayer({ noiseOffset, amplitude, baseHeight }, col) {\n  stroke(col);\n  for (let x = 0; x < width; x++) {\n    const sampleX = x + scrollOffset;\n    const h = amplitude * noise(NOISE_SCALE * sampleX + noiseOffset);\n    line(x, height, x, height - h - baseHeight);\n  }\n}\n\nfunction drawLasers() {\n  push();\n  strokeWeight(LASER_WEIGHT);\n\n  const speed = partyMode ? LASER_SWAY_SPEED * SWAY_BOOST : LASER_SWAY_SPEED;\n  const sway = sin(frameCount * speed) * LASER_SWAY;\n\n  // strobe: lasrarna blinkar av och på i partyläge\n  const strobeOn = !partyMode || sin(frameCount * STROBE_SPEED) > -0.2;\n\n  if (strobeOn) {\n    for (const laser of laserSources) {\n      const movingAngle = laser.angle + sway;\n\n      const startX = laser.x;\n      const startY = height - 30;\n      const endX = startX + sin(movingAngle) * LASER_LENGTH;\n      const endY = startY - cos(movingAngle) * LASER_LENGTH;\n\n      drawingContext.shadowBlur = LASER_GLOW;\n      drawingContext.shadowColor = `rgb(${laser.color.join(\",\")})`;\n\n      stroke(...laser.color, 250);\n      line(startX, startY, endX, endY);\n    }\n  }\n\n  drawingContext.shadowBlur = 0;\n  pop();\n}\n\n// Konfettipartiklar som skjuts upp från skogen\nfunction updateParticles() {\n  if (toggleState && partyMode) {\n    for (let i = 0; i < PARTICLES_PER_FRAME; i++) {\n      const c = random(LASER_COLORS);\n      particles.push({\n        x: random(width),\n        y: height - 40,\n        vx: random(-2, 2),\n        vy: random(-12, -5),\n        size: random(4, 9),\n        color: c,\n        life: 255,\n      });\n    }\n  }\n\n  push();\n  noStroke();\n  for (let i = particles.length - 1; i >= 0; i--) {\n    const p = particles[i];\n    p.x += p.vx;\n    p.y += p.vy;\n    p.vy += GRAVITY;\n    p.life -= 3;\n\n    if (p.life <= 0) {\n      particles.splice(i, 1);\n      continue;\n    }\n\n    drawingContext.shadowBlur = 15;\n    drawingContext.shadowColor = `rgb(${p.color.join(\",\")})`;\n    fill(...p.color, p.life);\n    circle(p.x, p.y, p.size);\n  }\n  drawingContext.shadowBlur = 0;\n  pop();\n}\n\n// Ritar en text centrerad på canvasen i angiven font\nfunction centeredText(str, font, y) {\n  textFont(font);\n  textAlign(LEFT, CENTER);\n  text(str, (width - textWidth(str)) / 2, y);\n}\n\nfunction drawTitle() {\n  textSize(TITLE_SIZE);\n  textStyle(NORMAL);\n\n  if (toggleState) {\n    // natt: glöd\n    drawingContext.shadowBlur = 20;\n    drawingContext.shadowColor = color(115, 0, 230);\n    fill(255, 100, 255);\n    stroke(255);\n    strokeWeight(2);\n  } else {\n    // dag: ingen glöd\n    drawingContext.shadowBlur = 0;\n    fill(255);\n    stroke(30, 90, 40);\n    strokeWeight(3);\n  }\n\n  textAlign(LEFT, CENTER);\n\n  // rad 1: \"SKOG\" i fontBody, centrerad och alltid på samma plats\n  textFont(fontBody);\n  const skogW = textWidth(\"SKOG\");\n  const skogX = (width - skogW) / 2;\n  text(\"SKOG\", skogX, TITLE_Y1);\n\n  if (toggleState) {\n    // natt: \"S\" i graffitifont direkt efter SKOG (SKOG flyttas inte)\n    textFont(fontGraffiti);\n    text(\"S\", skogX + skogW, TITLE_Y1);\n\n    // rad 2: \"RAVE\" i graffitifont, centrerad\n    centeredText(\"RAVE\", fontGraffiti, TITLE_Y2);\n  }\n\n  // namn: samma font som SKOG\n  drawingContext.shadowBlur = 0;\n  noStroke();\n  fill(255);\n  textFont(fontBody);\n  textStyle(NORMAL);\n  textSize(16);\n  textAlign(CENTER, CENTER);\n  text(\"Tuva Naring\", width / 2, 25);\n}\n\n// musklick: växla dag/natt och starta partyläge\nfunction mousePressed() {\n  partyMode = true; //Claude la till partymode med strobe effekt och konfetti om man håller ner musen. Det var dens egna tillägg som skulle passa estetiken. Bra tillägg och uppskattar att den använde sig av redan existerande laser för att göra en extra effekt. \n  toggleState = !toggleState;\n\n  if (toggleState) {\n    layerColors = forestLayers.map(() => color(0));\n  } else {\n    layerColors = [...originalColors];\n    bgColor = originalBgColor;\n  }\n}\n\n// släpp musen: tillbaka till lugnt läge\nfunction mouseReleased() {\n  partyMode = false;\n}\n\n// Inte så intuitiv interaktion att man måste hålla ner när det är dag och när man släpper är man kvar på natt fast utan \"partymode\" och om man försöker hålla ner igen medan man är i nattmode så kommer man tillbaka till dag istället för att aktivera partymode igen. \n", "assets": {"RockSalt-Regular.ttf": {"mime": "font/ttf", "b64": ""}, "galaxysky.jpg": {"mime": "image/webp", "b64": ""}, "PermanentMarker-Regular.ttf": {"mime": "font/ttf", "b64": ""}}});
